66	            return null;
67	        }
68	        return owner.getLastName() + ", " + owner.getFirstName();
69	    }
70	
71	    /**
72	     * Builds an owner's initials as the upper-cased first letters of the first and last
73	     * name, dot-separated with a trailing dot (e.g. {@code "J.S."}).
74	     */
75	    protected String formatInitials(Owner owner) {
76	        if (owner == null) {
77	            return null;
78	        }
79	        return initial(owner.getFirstName()) + initial(owner.getLastName());
80	    }
81	
82	    private String initial(String name) {
83	        return Character.toUpperCase(name.charAt(0)) + ".";
84	    }
85	
