31	import org.springframework.samples.petclinic.rest.controller.CityCapacityValidator;
32	import org.springframework.samples.petclinic.rest.controller.DailyRegistrationLimitValidator;
33	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
34	import org.springframework.samples.petclinic.rest.controller.EmailNormalizer;
35	import org.springframework.samples.petclinic.rest.controller.HouseholdAssigner;
36	import org.springframework.samples.petclinic.rest.controller.HouseholdDuplicateValidator;
37	import org.springframework.samples.petclinic.rest.controller.OwnerAuditLogger;
38	import org.springframework.samples.petclinic.rest.controller.OwnerFieldsValidator;
39	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
40	import org.springframework.samples.petclinic.model.Owner;
41	import org.springframework.samples.petclinic.model.Pet;
42	import org.springframework.samples.petclinic.model.Visit;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.WebDataBinder;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.InitBinder;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final OwnerFieldsValidator ownerFieldsValidator;
79	
80	    private final TelephoneNormalizer telephoneNormalizer;
81	
82	    private final EmailNormalizer emailNormalizer;
83	
84	    private final AddressNormalizer addressNormalizer;
85	
86	    private final HouseholdDuplicateValidator householdDuplicateValidator;
87	
88	    private final HouseholdAssigner householdAssigner;
89	
90	    private final CityCapacityValidator cityCapacityValidator;
91	
92	    private final DailyRegistrationLimitValidator dailyRegistrationLimitValidator;
93	
94	    private final BusinessDayAdjuster businessDayAdjuster;
95	
96	    private final OwnerAuditLogger ownerAuditLogger;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper,
102	                                 OwnerFieldsValidator ownerFieldsValidator,
103	                                 TelephoneNormalizer telephoneNormalizer,
104	                                 EmailNormalizer emailNormalizer,
105	                                 AddressNormalizer addressNormalizer,
106	                                 HouseholdDuplicateValidator householdDuplicateValidator,
107	                                 HouseholdAssigner householdAssigner,
108	                                 CityCapacityValidator cityCapacityValidator,
109	                                 DailyRegistrationLimitValidator dailyRegistrationLimitValidator,
110	                                 BusinessDayAdjuster businessDayAdjuster,
111	                                 OwnerAuditLogger ownerAuditLogger) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	        this.ownerFieldsValidator = ownerFieldsValidator;
117	        this.telephoneNormalizer = telephoneNormalizer;
118	        this.emailNormalizer = emailNormalizer;
119	        this.addressNormalizer = addressNormalizer;
120	        this.householdDuplicateValidator = householdDuplicateValidator;
121	        this.householdAssigner = householdAssigner;
122	        this.cityCapacityValidator = cityCapacityValidator;
123	        this.dailyRegistrationLimitValidator = dailyRegistrationLimitValidator;
124	        this.businessDayAdjuster = businessDayAdjuster;
125	        this.ownerAuditLogger = ownerAuditLogger;
126	    }
127	
128	    /**
129	     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
130	     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
131	     */
132	    @InitBinder("ownerFieldsDto")
133	    void initOwnerFieldsBinder(WebDataBinder binder) {
134	        binder.addValidators(ownerFieldsValidator);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
140	        Collection<Owner> owners;
141	        if (lastName != null) {
142	            owners = this.clinicService.findOwnerByLastName(lastName);
143	        } else {
144	            owners = this.clinicService.findAllOwners();
145	        }
146	        if (owners.isEmpty()) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
155	        Owner owner = this.clinicService.findOwnerById(ownerId);
156	        if (owner == null) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
165	        HttpHeaders headers = new HttpHeaders();
166	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
167	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
168	        LocalDate registrationDate = owner.getRegistrationDate() != null
169	            ? owner.getRegistrationDate() : LocalDate.now();
170	        owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(registrationDate));
171	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
172	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
173	            throw new DuplicateTelephoneException(telephone);
174	        }
175	        dailyRegistrationLimitValidator.validate(owner.getRegistrationDate());
176	        cityCapacityValidator.validate(owner);
177	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
178	            householdAssigner.assignSharedHousehold(owner);
179	        } else {
180	            householdDuplicateValidator.validate(owner);
181	        }
182	        owner.setTelephone(telephone);
183	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
184	        this.clinicService.saveOwner(owner);
185	        ownerAuditLogger.logCreated(owner);
186	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
187	        headers.setLocation(UriComponentsBuilder.newInstance()
188	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
189	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
195	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
196	        if (currentOwner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        currentOwner.setAddress(ownerFieldsDto.getAddress());
200	        currentOwner.setCity(ownerFieldsDto.getCity());
201	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
202	        currentOwner.setLastName(ownerFieldsDto.getLastName());
203	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
204	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
205	        this.clinicService.saveOwner(currentOwner);
206	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Transactional
211	    @Override
212	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        this.clinicService.deleteOwner(owner);
218	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        HttpHeaders headers = new HttpHeaders();
229	        Pet pet = petMapper.toPet(petFieldsDto);
230	        owner.setId(ownerId);
231	        pet.setOwner(owner);
232	        pet.getType().setName(null);
233	        this.clinicService.savePet(pet);
234	        PetDto petDto = petMapper.toPetDto(pet);
235	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
236	            .buildAndExpand(pet.getId()).toUri());
237	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
238	    }
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
243	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
244	        if (currentOwner != null) {
245	            Pet currentPet = this.clinicService.findPetById(petId);
246	            if (currentPet != null) {
247	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
248	                currentPet.setName(petFieldsDto.getName());
249	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
250	                this.clinicService.savePet(currentPet);
251	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
252	            }
253	        }
254	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
260	        HttpHeaders headers = new HttpHeaders();
261	        Visit visit = visitMapper.toVisit(visitFieldsDto);
262	        Pet pet = new Pet();
263	        pet.setId(petId);
264	        visit.setPet(pet);
