    @Transactional(readOnly = true)
    public long countOwnersRegisteredOn(LocalDate date) throws DataAccessException {
        return ownerRepository.findAll().stream()
            .filter(existing -> date.equals(existing.getRegistrationDate()))
            .count();
    }

